"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9526],{10369:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PropsPage","desc":"The Props tab: section buttons, a grid of prop pictures, and the options of the picked prop.\\nWith Collapse props after picking one on, picking a prop folds the grid down to the row that\\nholds it, with a button to show all again.\\n\\nThe pictures are drawn in ViewportFrames, so the parts only exist inside the panel and never\\nreach the place. They are colored by the color theme and redrawn when it changes.","source":{"line":14,"path":"src/Ui/Pages/Props.luau"}}')}}]);